/**
 * The REAL sign-in door of the new architecture — `cowork.tracy.site/login`, generated by `apps/tracy-web`.
 *
 * The `WorkerAuthPages` story next to this one renders the OLD Worker's page (`workers/fleet-bar`), which only
 * serves `cowork.tracy.ai` until Plan 5 cuts over. The two pages share one design but are two
 * sources, and they have drifted: the tracy-web page shows the Google/GitHub buttons BY THE ENV of the machine running it
 * (`config.js` `readOAuth`), while the old Worker hard-codes both. Review the `tracy.site` login
 * HERE. Measured 14/09: dev only has Google because its env has no `GITHUB_OAUTH_CLIENT_ID/SECRET` yet.
 *
 * Same rule as the other story: import the page-generating function itself (`identity/pages.js`, a pure function — split out
 * of `route.js` precisely so the story does not pull Hono and the store into the bench), rendered in an `<iframe srcDoc>`
 * because the page carries its own `<style>` and must not receive the bench's Tailwind.
 */
import type { Meta, StoryObj } from '@storybook/react-vite'
import { expect } from 'storybook/test'

import {
  desktopConfirmPage,
  deviceApprovedPage,
  deviceConfirmPage,
  deviceDeniedPage,
  loginPage,
  signInFailedPage
} from '../../../../../../apps/tracy-web/src/identity/pages.js'

const ORIGIN = 'https://cowork.tracy.site'
/** What a configured provider looks like to `loginPage`: the page only asks whether the key exists. */
const GOOGLE = { google: { id: 'x', secret: 'y' } }
const BOTH = { ...GOOGLE, github: { id: 'x', secret: 'y' } }

function TracyWebPage({ html, title }: { html: string; title: string }) {
  return <iframe srcDoc={html} title={title} className="h-full w-full border-0" />
}

const meta = {
  component: TracyWebPage,
  parameters: { layout: 'fullscreen' }
} satisfies Meta<typeof TracyWebPage>

export default meta
type Story = StoryObj<typeof meta>

/** Exactly what `cowork.tracy.site` shows today: one provider configured. */
export const SignInGoogleOnly: Story = {
  name: 'Sign in - Google only (dev today)',
  args: { title: 'Sign in to Tracy', html: loginPage({ origin: ORIGIN, next: '/', oauth: GOOGLE }) },
  play: async ({ args }) => {
    expect(args.html).toContain('Continue with email')
    expect(args.html).toContain('/signin/google')
    expect(args.html).not.toContain('/signin/github')
  }
}

/** Both providers configured — what the page shows once the env carries GitHub too. */
export const SignInBoth: Story = {
  name: 'Sign in - Google + GitHub',
  args: { title: 'Sign in to Tracy', html: loginPage({ origin: ORIGIN, next: '/', oauth: BOTH }) },
  play: async ({ args }) => {
    expect(args.html.indexOf('/signin/google')).toBeLessThan(args.html.indexOf('/signin/github'))
  }
}

export const SignInNoProvider: Story = {
  name: 'Sign in - email only (no OAuth env)',
  args: { title: 'Sign in to Tracy', html: loginPage({ origin: ORIGIN, next: '/' }) },
  play: async ({ args }) => {
    expect(args.html).not.toContain('or continue with')
  }
}

