/**
 * The pages that are one card of text. Each is the real renderer's output, so the bench shows
 * what the server sends: one `<main>`, and every word inside a padded card part. These pages follow
 * `prefers-color-scheme`, not the bench's theme toggle; switch the OS or the browser's emulation to
 * see the other theme.
 */
const inPaddedPart = (html: string) => {
  const page = new DOMParser().parseFromString(html, 'text/html')
  expect(page.querySelectorAll('main')).toHaveLength(1)
  const card = page.querySelector('main > div.card')
  expect(card).not.toBeNull()
  for (const el of card?.querySelectorAll('h1, p, form, a') ?? [])
    expect(el.closest('.card-header, .card-content, .card-footer')).not.toBeNull()
}

export const SignInCancelled: Story = {
  name: 'Sign-in did not finish - cancelled at Google',
  args: {
    title: 'Sign-in did not finish',
    html: signInFailedPage({ reason: 'cancelled', provider: 'google', next: '/acme/', origin: ORIGIN })
  },
  play: async ({ args }) => {
    expect(args.html).toContain('cancelled at Google')
    expect(args.html).not.toContain('took too long')
    inPaddedPart(args.html)
  }
}

export const SignInStale: Story = {
  name: 'Sign-in did not finish - stale or foreign state',
  args: {
    title: 'Sign-in did not finish',
    html: signInFailedPage({ reason: 'state', provider: 'github', origin: ORIGIN })
  },
  play: async ({ args }) => {
    expect(args.html).toContain('took too long')
    inPaddedPart(args.html)
  }
}

